def hidden_rule_fn(state, grid_size=8):
    def _wd(a, b, gs):
        d = (b - a) % gs
        return d - gs if d > gs // 2 else d
    def _dist(p, q, gs):
        dx = abs(_wd(p['x'], q['x'], gs)); dy = abs(_wd(p['y'], q['y'], gs))
        return max(dx, dy) + (0 if p['type'] == q['type'] else 1)
    def _mv_a(p, tgt, gs, sign):
        ddx = _wd(p['x'], tgt['x'], gs); ddy = _wd(p['y'], tgt['y'], gs)
        if abs(ddx) >= abs(ddy):
            sx = 0 if ddx == 0 else (1 if ddx > 0 else -1); sy = 0
        else:
            sx = 0; sy = 0 if ddy == 0 else (1 if ddy > 0 else -1)
        return ((p['x'] + sign*sx) % gs, (p['y'] + sign*sy) % gs)
    def _mv_b(p, tgt, gs, sign):
        ddx = _wd(p['x'], tgt['x'], gs); ddy = _wd(p['y'], tgt['y'], gs)
        sx = 0 if ddx == 0 else (1 if ddx > 0 else -1)
        sy = 0 if ddy == 0 else (1 if ddy > 0 else -1)
        return ((p['x'] + sign*sx) % gs, (p['y'] + sign*sy) % gs)
    nxt = []
    for i, p in enumerate(state):
        if p['type'] == 'GLORP':
            target_type = 'GLORP' if 'cross' == 'same' else 'ZEX'
            cands = [q for j, q in enumerate(state) if q['type'] == target_type and j != i]
            if not cands:
                nxt.append(dict(p)); continue
            tgt = min(cands, key=lambda q: (_dist(p, q, grid_size), q['x'], q['y']))
            nx, ny = _mv_a(p, tgt, grid_size, -1)
            nxt.append({'type': p['type'], 'x': nx, 'y': ny})
        elif p['type'] == 'ZEX':
            target_type = 'GLORP' if 'same' == 'cross' else 'ZEX'
            cands = [q for j, q in enumerate(state) if q['type'] == target_type and j != i]
            if not cands:
                nxt.append(dict(p)); continue
            tgt = min(cands, key=lambda q: (_dist(p, q, grid_size), q['x'], q['y']))
            nx, ny = _mv_b(p, tgt, grid_size, 1)
            nxt.append({'type': p['type'], 'x': nx, 'y': ny})
        else:
            nxt.append(dict(p))
    return nxt

