def hidden_rule_fn(state):
    rows, cols = 3, 5
    if len(state) != rows * cols:
        return list(state)
    grid = [state[r*cols:(r+1)*cols] for r in range(rows)]
    nxt = []
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if r % 2 == 0:
                nv = (v + grid[r][(c+1)%cols]) % 5
            else:
                nv = (v ^ grid[(r+1)%rows][c]) % 5
            nxt.append(nv)
    return nxt

